/**
 * `int(str)` with CPython's exact grammar, returning a BigInt so that
 * arbitrary-precision arithmetic keeps working.
 */

import { PyValueError } from './errors.mjs';
import { reprString, truncateRepr } from './repr.mjs';
import { decimalValue, isPySpace } from './unicodedata.mjs';

/** CPython formats this message with `%.200R`, i.e. a 200 character cap. */
const MESSAGE_REPR_LIMIT = 200;

function invalidLiteral(text) {
  const shown = truncateRepr(reprString(text), MESSAGE_REPR_LIMIT);
  return new PyValueError(`invalid literal for int() with base 10: ${shown}`);
}

function stripPySpace(characters) {
  let start = 0;
  let end = characters.length;
  while (start < end && isPySpace(characters[start].codePointAt(0))) start += 1;
  while (end > start && isPySpace(characters[end - 1].codePointAt(0))) end -= 1;
  return characters.slice(start, end);
}

/**
 * Grammar accepted by `int(x, 10)`:
 *   whitespace* [+-]? digit (['_']? digit)* whitespace*
 * where `digit` is any Unicode decimal digit and `_` may only separate digits.
 *
 * @param {string} text
 * @returns {bigint}
 */
export function pyInt(text) {
  const characters = stripPySpace(Array.from(text));
  let index = 0;
  let negative = false;

  if (index < characters.length && (characters[index] === '+' || characters[index] === '-')) {
    negative = characters[index] === '-';
    index += 1;
  }

  let digits = '';
  let previousWasDigit = false;
  for (; index < characters.length; index += 1) {
    const character = characters[index];
    if (character === '_') {
      // An underscore must sit between two digits.
      if (!previousWasDigit) throw invalidLiteral(text);
      previousWasDigit = false;
      continue;
    }
    const value = decimalValue(character.codePointAt(0));
    if (value < 0) throw invalidLiteral(text);
    digits += String(value);
    previousWasDigit = true;
  }

  if (digits === '' || !previousWasDigit) throw invalidLiteral(text);
  const magnitude = BigInt(digits);
  return negative ? -magnitude : magnitude;
}
